"""Crew 4: Interview Prep - 4 agents, 5 tasks (--lite = first 2 tasks/agents)."""
from _compat import Agent, Task, Crew, Process, get_serper_tool, set_meta
from core.model_router import get_llm, tier_for, max_iter_for
from user_profile import profile_as_text_full

def build_crew(lite=False, economy=False):
    def mk(role,goal,backstory,tools,key,kind="writing"):
        return Agent(role=role,goal=goal,backstory=backstory,tools=tools,verbose=True,llm=get_llm(tier_for(key,economy),economy),max_iter=max_iter_for(kind,economy))
    question_generator = mk("Interview Question Specialist","Generate realistic, role-specific interview questions that match what candidates will actually face in interviews","You have extensive experience in recruiting and interviewing for various roles. You understand what different types of hiring managers look for and can predict the questions they're likely to ask.",[get_serper_tool()],"question_generator")  # industry_knowledge_base, question_database, role_analyzer dropped
    answer_coach = mk("Interview Answer Strategist","Develop personalized answer frameworks that highlight the candidate's best qualifications and experiences for each question","You are an expert interview coach who knows how to help candidates identify their strongest examples and frame them compellingly. You understand what hiring managers want to hear.",[],"answer_coach")  # experience_analyzer, story_framework_builder, impact_calculator dropped
    mock_interview_designer = mk("Mock Interview Facilitator","Design realistic mock interview scenarios that simulate the actual interview experience and help candidates practice effectively","You have conducted thousands of interviews and understand how they typically flow. You can create realistic scenarios that prepare candidates for the real experience.",[],"mock_interview_designer")  # interview_simulator, conversation_flow_builder, feedback_generator dropped as tools
    interview_simulator = mk("Interactive Interview Simulator","Conduct realistic mock interviews that adapt to candidate responses and provide real-time feedback","You are an experienced interviewer who can simulate different interviewing styles and adapt questions based on candidate responses. You provide constructive feedback to help candidates improve.",[],"interview_simulator")  # conversation_manager, response_analyzer, feedback_system dropped
    profile=profile_as_text_full()
    generate_questions_task = Task(description="Generate a comprehensive set of interview questions for a {job_title} position at {company_name}. Include: 1) 5 behavioral questions relevant to this role, 2) 3-5 technical questions matching the required skills, 3) 2-3 company-specific questions, 4) 2 situational questions related to common challenges in this role, 5) Questions about career goals and motivation. Ensure questions reflect current industry standards.", agent=question_generator, expected_output="A categorized list of realistic interview questions with explanations of why each question is relevant to this role")
    set_meta(generate_questions_task, "task_name", "generate_questions_task")
    develop_answers_task = Task(description="For each interview question, develop a personalized answer framework using the candidate's background. For behavioral questions, identify specific experiences from their resume and structure them using STAR method. For technical questions, outline key concepts to cover and examples to use. Include: 1) Main points to cover, 2) Specific examples from their experience, 3) Key metrics or outcomes to mention, 4) How to connect the answer to the role requirements. Candidate profile:\n"+profile+" Use only experiences and metrics that appear in the profile.", agent=answer_coach, expected_output="Detailed answer frameworks for each question with specific examples and talking points tailored to the candidate's experience", context=[generate_questions_task])
    set_meta(develop_answers_task, "task_name", "develop_answers_task")
    if lite:
        crew=Crew(agents=[question_generator, answer_coach], tasks=[generate_questions_task, develop_answers_task], process=Process.sequential, verbose=True); set_meta(crew, "task_map", {"generate_questions_task":generate_questions_task,"develop_answers_task":develop_answers_task}); return crew
    create_mock_interview_task = Task(description="Design a complete mock interview scenario for the {job_title} position. Include: 1) Opening questions and small talk, 2) Main interview questions in logical order, 3) Likely follow-up questions based on common answers, 4) Technical or case study components if relevant, 5) Questions for the candidate to ask, 6) Closing and next steps discussion. Make it feel like a real 45-60 minute interview.", agent=mock_interview_designer, expected_output="A complete mock interview script with questions, expected flow, and guidance for realistic practice", context=[generate_questions_task, develop_answers_task])
    set_meta(create_mock_interview_task, "task_name", "create_mock_interview_task")
    simulate_interview_task = Task(description="Conduct an interactive mock interview for the {job_title} position. Ask questions one at a time, analyze responses, and ask appropriate follow-up questions. Adapt the interview style to match the company culture. After each answer, provide brief feedback on: 1) Content quality, 2) Communication style, 3) Specific improvements, 4) What worked well. End with overall performance summary. If no candidate responses are provided, do not invent them. Instead, present the interview questions one at a time, describe what a strong answer would contain, and list the feedback criteria.", agent=interview_simulator, expected_output="An interactive interview experience with real-time feedback and a comprehensive performance evaluation", context=[create_mock_interview_task])
    set_meta(simulate_interview_task, "task_name", "simulate_interview_task")
    specialized_prep_task = Task(description="Based on the {job_title} role, create specialized interview preparation materials: For technical roles: coding problems and system design questions. For consulting: case study frameworks and business problems. For leadership: situational leadership scenarios. For creative roles: portfolio discussion points. Include practice materials and evaluation criteria. Choose only the role type(s) that fit the job title rather than producing all four.", agent=question_generator, expected_output="Role-specific interview preparation materials with practice exercises and success criteria", context=[generate_questions_task])
    set_meta(specialized_prep_task, "task_name", "specialized_prep_task")
    tasks=[generate_questions_task, develop_answers_task, create_mock_interview_task, simulate_interview_task, specialized_prep_task]
    crew=Crew(agents=[question_generator, answer_coach, mock_interview_designer, interview_simulator], tasks=tasks, process=Process.sequential, verbose=True)
    set_meta(crew, "task_map", {t.task_name:t for t in tasks}); return crew
build_interview_prep_crew = build_crew
